"use client";

import { useEffect, useState } from "react";

const rand = (n: number) => {
  const x = Math.sin(n * 9301 + 49297) * 233280;
  return x - Math.floor(x);
};

export function ScatterTextTailwind({ text = "Pieces fall into place", spread = 240 }) {
  const [together, setTogether] = useState(false);
  useEffect(() => {
    const id = requestAnimationFrame(() => requestAnimationFrame(() => setTogether(true)));
    return () => cancelAnimationFrame(id);
  }, []);
  return (
    <h2
      onPointerEnter={() => setTogether(false)}
      onPointerLeave={() => setTogether(true)}
      className="select-none px-8 py-4 text-center text-[56px] font-extrabold tracking-tighter text-zinc-100"
    >
      <span className="sr-only">{text}</span>
      {Array.from(text).map((ch, i) => {
        const a = rand(i) * Math.PI * 2;
        const d = spread * (0.35 + rand(i + 1) * 0.65);
        const scattered = "translate(" + Math.cos(a) * d + "px," + Math.sin(a) * d * 0.6 + "px) rotate(" + (rand(i + 2) - 0.5) * 300 + "deg)";
        return (
          <span
            key={i}
            aria-hidden
            className={"inline-block transition-all duration-1000 ease-[cubic-bezier(0.16,1,0.3,1)] " + (together ? "opacity-100" : "opacity-60")}
            style={{ transform: together ? "none" : scattered, transitionDelay: i * 0.025 + "s" }}
          >
            {ch === " " ? "\u00a0" : ch}
          </span>
        );
      })}
    </h2>
  );
}
